// translateJLPTKanjiReadingText applies only an explicit reviewed entry. An
// unknown value remains byte-for-byte unchanged, which preserves Japanese text.
func translateJLPTKanjiReadingText(field, source string) string {
	if translated, ok := jlptKanjiReadingEnglish[field][source]; ok {
		return translated
	}
	return source
}
